def query_store_registry(niche: str, platform: str, country: str, limit: int = 50) -> List[Dict[str, Any]]:
    """Queries the verified store database for high-intent e-commerce storefronts."""
    nl = niche.lower().strip()
    c_target = country.upper().strip()
    
    matches = []
    
    # 1. Exact niche & country match
    for item in STORE_REGISTRY:
        n_match = (
            item["niche"].lower() in nl or
            nl in item["niche"].lower() or
            (nl in ["shoes", "footwear", "sneakers", "boots", "trainers"] and item["niche"] == "Footwear") or
            (nl in ["streetwear", "hoodies", "apparel", "clothing", "fashion", "menswear", "womenswear"] and item["niche"] == "Streetwear") or
            (nl in ["cosmetics", "skincare", "beauty", "makeup"] and item["niche"] == "Cosmetics") or
            (nl in ["jewelry", "jewellery", "accessories", "rings"] and item["niche"] == "Jewelry") or
            (nl in ["supplements", "vitamins", "wellness", "nutrition"] and item["niche"] == "Supplements") or
            (nl in ["watches", "timepieces", "luxury"] and item["niche"] == "Watches") or
            (nl in ["home", "decor", "furniture", "kitchen"] and item["niche"] == "Home")
        )
        if n_match and item.get("country", "").upper() == c_target:
            matches.append(dict(item))
            if len(matches) >= limit:
                return matches

    # 2. If limit not yet reached, match niche across all regions
    if len(matches) < limit:
        for item in STORE_REGISTRY:
            n_match = (
                item["niche"].lower() in nl or
                nl in item["niche"].lower() or
                (nl in ["shoes", "footwear", "sneakers", "boots", "trainers"] and item["niche"] == "Footwear") or
                (nl in ["streetwear", "hoodies", "apparel", "clothing", "fashion", "menswear", "womenswear"] and item["niche"] == "Streetwear") or
                (nl in ["cosmetics", "skincare", "beauty", "makeup"] and item["niche"] == "Cosmetics") or
                (nl in ["jewelry", "jewellery", "accessories", "rings"] and item["niche"] == "Jewelry") or
                (nl in ["supplements", "vitamins", "wellness", "nutrition"] and item["niche"] == "Supplements") or
                (nl in ["watches", "timepieces", "luxury"] and item["niche"] == "Watches") or
                (nl in ["home", "decor", "furniture", "kitchen"] and item["niche"] == "Home")
            )
            if n_match and item not in matches:
                matches.append(dict(item))
                if len(matches) >= limit:
                    return matches

    # 3. Fallback: all available active stores if custom niche
    if len(matches) < limit:
        for item in STORE_REGISTRY:
            if item not in matches:
                matches.append(dict(item))
                if len(matches) >= limit:
                    return matches

    return matches[:limit]
